            "id": "metadata",
            "direction": "output",
            "kind": "text",
            "format": "JSON",
            "traits": {
              "schema": "schemaxis.exiftool.metadata/1"
            },
            "losses": [
              "Scoped selected observations only; every other tag is unassessed."
            ],
            "scope": "IDs, digests, observed values, scoped native observations, review and losses."
          },
