            "id": "tracks",
            "direction": "input",
            "kind": "text",
            "format": "GPX",
            "traits": {
              "versions": "GPX 1.0 and 1.1",
              "maxFilesPerRun": 8,
              "maxBytesPerFile": 33554432,
              "maxBytesTotal": 67108864
            },
            "losses": [
              "Timed track fixes only: waypoints, routes, extensions and every element but trkpt latitude, longitude, time and elevation are not used; the path between fixes is unknown, no accuracy is claimed and the vertical reference of an elevation is declared by the author."
            ],
            "scope": "geotagFromTrack captures 1 to 8 local regular GPX files byte for byte (DTD, entities and external references refused); a text artifact of an earlier operation (for example a published plan file) can be bound to a plan option."
          },
          {
            "id": "time-location-reports",
            "direction": "output",
            "kind": "text",
            "format": "JSON and typed CSV",
            "traits": {
              "time": "schemaxis.exiftool.time-report/1",
              "location": "schemaxis.exiftool.location-report/1"
            },
            "losses": [
              "Analysis and plans of declared inputs: references, assumed offsets and positions are published as declared and are never verified; no time zone, daylight-saving rule, datum or vertical conversion."
            ],
            "scope": "time-report.json and time-report.csv (reconcileTime), location-report.json and location.csv (locate), time-correction-plan.json, location-plan.json, geotag-plan.json, track-report.json, write-report.json and residual.json (the write operations)."
          }
        ],
        "inspection": [
          {
            "panel": "text",
            "scope": "Read the typed records, manifests, findings and comparisons.",
            "limits": "Observed metadata only; no image display, no editing, no capture-truth or privacy-certification claim."
          }
        ],
        "authoring": {
          "model": "document",
          "example": "baseline",
          "reuse": "Edit item IDs, paths, pins, sidecars or the folder, profiles, rules and baseline; plan fresh and verify. Same-path byte changes and folder membership changes invalidate workflow reuse."
        },
        "features": {
          "workflow": {
            "status": "supported",
            "scope": "The typed inventory table is consumed by Calc through normal workflow jobs."
          },
          "composition": {
            "status": "supported",
            "scope": "Shared expressions and finite visits resolve before planning."
          },
          "reusable-inputs": {
            "status": "supported",
            "scope": "Captured item and sidecar bytes participate in reuse identity; a folder also contributes a manifest digest so an added or removed file invalidates reuse; captured GPX track bytes and plan-file bytes of the time and location operations are reusable inputs, so a changed track or plan invalidates reuse and a changed modification time alone does not."
          },
          "source-authoring": {
            "status": "supported",
            "scope": "Shared JSON editing, undo and validation support the closed document."
          },
          "property-authoring": {
            "status": "supported",
            "scope": "Shared forms expose the media set (items or folder), profiles, rules and baseline."
          },
          "native-inspection": {
            "status": "unsupported",
            "scope": "No interactive native-inspection hook; the metadata summary is a publication."
          },
          "mpi": {
            "status": "unsupported",
            "scope": "Serial local subprocess only."
          },
          "time-batches": {
            "status": "unsupported",
            "scope": "Items are explicit files or a declared folder, not a temporal dataset."
          },
          "live-editing": {
            "status": "unsupported",
            "scope": "No live application connection."
          },
          "native-save": {
            "status": "unsupported",
            "scope": "Originals are never written, removed or stripped: every writing operation (editMetadata, removeMetadata, correctTime, setLocation, geotagFromTrack, copyMetadata, applySidecar) publishes new copies of the same container into the run."
          },
          "conversion": {
            "status": "unsupported",
            "scope": "Metadata reading and writing only; no format conversion and no re-encoding of image data."
          }
        },
